--- 684/nes_native_runtime165.c
+++ 685/nes_native_runtime165.c
@@ -46,7 +46,7 @@
   if(r->state==NES_NATIVE165_COMMITTED)s->prefetch_left=7;
   if(reason==3)reason=2;
  }
- if(reason==4 || (s->prefetch_left && (input_wait || (reason==2 && !progress)))){
+ if(reason==4 || (s->prefetch_left && (input_wait || reason==2))){
   if(!check(ctx))return false;
   nes_native165_consumed(r);
   while(s->prefetch_left && r->state!=NES_NATIVE165_COMPLETE){
@@ -56,7 +56,9 @@
     * Empty STATUS and failed/partial IO cannot consume the seven-block cap. */
    if(r->next_token==before)break;
    --s->prefetch_left;progress=true;
-   /* Only sealed output may defer its next E0 until this bounded input
+   /* SEAL has no later output to issue: preceding retirement does not
+    * need another E0 before borrowing SPI. Full identity is still checked
+    * by the barrier before it returns. Only sealed output may defer its next E0 until this bounded input
     * batch ends. Every READ/POP retains CRC, identity and STOP checks. */
    if(reason!=2)break;
    if(!check(ctx))return false;
